O que acontece com este código?

struct Counter {
    var n = 0
    mutating func inc() { n += 1 }
}
let c = Counter()
c.inc()

Qual é a saída?

struct Counter {
    var n = 0
    mutating func inc() { n += 1 }
}
var a = Counter()
var b = a
b.inc()
print(a.n, b.n)

